insert into public.questions (exam_category, subject, topic, type, difficulty, body, body_hi, question_data, options, marks_correct, marks_wrong, explanation, explanation_hi, concept_group_id, source_type, source_citation, status)
values
('upsc','Geography','Geomorphology & Earth''s Interior','statement_based','medium','Consider the following statements about the Earth''s interior:','पृथ्वी के आंतरिक भाग के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The Mohorovičić discontinuity separates the crust from the mantle.", "The Gutenberg discontinuity separates the mantle from the outer core.", "The Lehmann discontinuity separates the outer core from the inner core."], "statements_hi": ["मोहोरोविसिक असंबद्धता भूपर्पटी (crust) को प्रावार (mantle) से अलग करती है।", "गुटेनबर्ग असंबद्धता प्रावार को बाहरी क्रोड से अलग करती है।", "लेहमन असंबद्धता बाहरी क्रोड को आंतरिक क्रोड से अलग करती है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'All three statements are correct. These boundaries were found from sudden changes in the speed of seismic waves: the ''Moho'' lies about 5-10 km below the ocean floor and 30-70 km below the continents; the Gutenberg discontinuity lies at about 2,900 km; and the Lehmann discontinuity at about 5,100 km. The Conrad discontinuity, often confused with them, lies within the continental crust.','तीनों कथन सही हैं। ये सीमाएँ भूकंपीय तरंगों की गति में अचानक परिवर्तनों से पता चलीं: ''मोहो'' समुद्र तल से लगभग 5-10 किमी और महाद्वीपों के नीचे 30-70 किमी गहराई पर है; गुटेनबर्ग असंबद्धता लगभग 2,900 किमी पर; और लेहमन असंबद्धता लगभग 5,100 किमी पर। इनसे प्रायः भ्रमित की जाने वाली कॉनराड असंबद्धता महाद्वीपीय भूपर्पटी के भीतर है।','geo-earth-interior-discontinuities','original_pattern_matched','NCERT Class XI, Fundamentals of Physical Geography -- Interior of the Earth.','draft'),
('upsc','Geography','Geomorphology & Earth''s Interior','statement_based','medium','Consider the following statements about seismic waves:','भूकंपीय तरंगों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["P-waves can travel through solids, liquids and gases.", "Surface waves are the first to be recorded on a seismograph.", "P-waves are transverse waves."], "statements_hi": ["P-तरंगें ठोस, द्रव और गैस, तीनों से गुज़र सकती हैं।", "भूकंपलेखी (seismograph) पर सबसे पहले सतही तरंगें दर्ज होती हैं।", "P-तरंगें अनुप्रस्थ (transverse) तरंगें हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct. Statement 3 is wrong: P-waves are longitudinal (compressional) waves -- they vibrate in the direction of travel -- which is why they pass through all states of matter; S-waves are the transverse ones. Statement 2 is wrong: P-waves are the fastest and arrive first, then S-waves; surface waves arrive last but cause most of the destruction.','केवल कथन 1 सही है। कथन 3 गलत है: P-तरंगें अनुदैर्ध्य (संपीडनी) तरंगें हैं, जो गति की दिशा में ही कंपन करती हैं, इसीलिए वे पदार्थ की सभी अवस्थाओं से गुज़रती हैं; अनुप्रस्थ तरंगें S-तरंगें हैं। कथन 2 गलत है: P-तरंगें सबसे तेज़ होती हैं और सबसे पहले पहुँचती हैं, फिर S-तरंगें; सतही तरंगें सबसे बाद में पहुँचती हैं पर अधिकांश विनाश वही करती हैं।','geo-seismic-waves-types','original_pattern_matched','NCERT Class XI, Fundamentals of Physical Geography -- Interior of the Earth.','draft'),
('upsc','Geography','Geomorphology & Earth''s Interior','statement_based','medium','Consider the following statements about plate boundaries:','प्लेट सीमाओं के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The East African Rift Valley is an example of a divergent boundary developing within a continent.", "The Andes were formed where an oceanic plate is subducting beneath a continental plate.", "The Red Sea is a zone where two plates are converging."], "statements_hi": ["पूर्वी अफ़्रीकी भ्रंश घाटी किसी महाद्वीप के भीतर विकसित हो रही अपसारी सीमा का उदाहरण है।", "एंडीज़ वहाँ बने जहाँ एक महासागरीय प्लेट महाद्वीपीय प्लेट के नीचे क्षेपित (subduct) हो रही है।", "लाल सागर ऐसा क्षेत्र है जहाँ दो प्लेटें अभिसरित हो रही हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct: East Africa is slowly being pulled apart, and the Nazca plate is sinking beneath the South American plate, raising the Andes and their volcanoes. Statement 3 is wrong: the Red Sea is a young divergent zone -- Africa and Arabia are moving apart, and a new ocean floor is forming along its axis.','कथन 1 और 2 सही हैं: पूर्वी अफ़्रीका धीरे-धीरे अलग हो रहा है, और नाज़्का प्लेट दक्षिण अमेरिकी प्लेट के नीचे धँस रही है, जिससे एंडीज़ और उनके ज्वालामुखी ऊपर उठे। कथन 3 गलत है: लाल सागर एक नया अपसारी क्षेत्र है; अफ़्रीका और अरब एक-दूसरे से दूर जा रहे हैं, और उसकी धुरी पर नया महासागरीय तल बन रहा है।','geo-plate-boundaries-examples','original_pattern_matched','NCERT Class XI, Fundamentals of Physical Geography -- Distribution of Oceans and Continents.','draft'),
('upsc','Geography','Geomorphology & Earth''s Interior','statement_based','medium','Consider the following statements about volcanoes:','ज्वालामुखियों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Shield volcanoes, such as Mauna Loa in Hawaii, are built mainly of fluid basaltic lava and have gentle slopes.", "Composite volcanoes, such as Mount Fuji, are built of alternating layers of lava and pyroclastic material.", "A caldera is a large depression formed when a volcano collapses after an eruption."], "statements_hi": ["शील्ड ज्वालामुखी, जैसे हवाई का मौना लोआ, मुख्य रूप से तरल बेसाल्टी लावा से बने होते हैं और उनके ढाल हल्के होते हैं।", "मिश्रित (composite) ज्वालामुखी, जैसे माउंट फ़ूजी, लावा और पाइरोक्लास्टिक पदार्थ की बारी-बारी की परतों से बने होते हैं।", "काल्डेरा एक बड़ा गर्त है जो उद्गार के बाद ज्वालामुखी के ढह जाने से बनता है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'All three statements are correct. The difference in shape follows the lava: basaltic lava is low in silica and runs far before cooling, while the more viscous, silica-rich magma of composite volcanoes traps gas and erupts explosively. Calderas can be huge -- Crater Lake in the United States and Lake Toba in Sumatra fill calderas.','तीनों कथन सही हैं। आकार का अंतर लावा से आता है: बेसाल्टी लावा में सिलिका कम होता है और ठंडा होने से पहले दूर तक बहता है, जबकि मिश्रित ज्वालामुखियों का अधिक चिपचिपा, सिलिका-प्रधान मैग्मा गैस को रोक लेता है और विस्फोटक उद्गार करता है। काल्डेरा बहुत बड़े हो सकते हैं; अमेरिका की क्रेटर झील और सुमात्रा की टोबा झील काल्डेरा में भरी हैं।','geo-volcano-types-caldera','original_pattern_matched','NCERT Class XI, Fundamentals of Physical Geography -- Interior of the Earth.','draft'),
('upsc','Geography','Geomorphology & Earth''s Interior','statement_based','medium','Consider the following statements about karst landforms:','कार्स्ट स्थलरूपों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Karst topography develops mainly on granite.", "Stalagmites hang down from the roofs of caves.", "Sinkholes are a feature of glaciated landscapes."], "statements_hi": ["कार्स्ट स्थलाकृति मुख्य रूप से ग्रेनाइट पर विकसित होती है।", "स्टैलेग्माइट गुफाओं की छतों से नीचे लटकते हैं।", "सिंकहोल (घोल-रंध्र) हिमनदित भू-दृश्यों की विशेषता हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": true}]'::jsonb,2,0.66,'None of the statements is correct. Karst forms on soluble rocks such as limestone and dolomite, which rainwater charged with carbon dioxide dissolves -- the Karst region of Slovenia gives the name. In caves, stalactites hang from the roof and stalagmites rise from the floor, and they may join as pillars. Sinkholes (dolines) form where the surface collapses into underground solution cavities, not through glaciers.','कोई भी कथन सही नहीं है। कार्स्ट चूना पत्थर और डोलोमाइट जैसी घुलनशील चट्टानों पर बनता है, जिन्हें कार्बन डाइऑक्साइड युक्त वर्षा-जल घोल देता है; स्लोवेनिया के कार्स्ट क्षेत्र से यह नाम आया। गुफाओं में स्टैलेक्टाइट छत से लटकते हैं और स्टैलेग्माइट फ़र्श से उठते हैं, और वे मिलकर स्तंभ बना सकते हैं। सिंकहोल (डोलाइन) वहाँ बनते हैं जहाँ सतह भूमिगत घुलन-गुहाओं में धँस जाती है, हिमनदों से नहीं।','geo-karst-landforms','original_pattern_matched','NCERT Class XI, Fundamentals of Physical Geography -- Landforms and their Evolution.','draft'),
('upsc','Geography','Geomorphology & Earth''s Interior','statement_based','medium','Consider the following statements about landforms:','स्थलरूपों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Oxbow lakes are formed when a meander of a river is cut off.", "The horns of a barchan dune point downwind.", "Mushroom rocks are formed mainly by glacial action."], "statements_hi": ["गोखुर झीलें तब बनती हैं जब नदी का कोई विसर्प (meander) कट जाता है।", "बरखान टिब्बे के सींग हवा की दिशा में आगे की ओर होते हैं।", "छत्रक (मशरूम) शिलाएँ मुख्य रूप से हिमनदी क्रिया से बनती हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct: a barchan is a crescent-shaped dune whose gentle slope faces the wind and whose horns trail away from it. Statement 3 is wrong: mushroom rocks are shaped by wind abrasion in deserts -- sand carried close to the ground wears the base of a rock faster than its top.','कथन 1 और 2 सही हैं: बरखान अर्धचंद्राकार टिब्बा है, जिसका हल्का ढाल हवा की ओर होता है और सींग हवा से दूर की ओर पीछे फैले होते हैं। कथन 3 गलत है: छत्रक शिलाएँ मरुस्थलों में पवन अपघर्षण से बनती हैं; ज़मीन के पास उड़ती रेत चट्टान के निचले भाग को ऊपरी भाग से अधिक तेज़ी से घिसती है।','geo-oxbow-barchan-mushroom','original_pattern_matched','NCERT Class XI, Fundamentals of Physical Geography -- Landforms and their Evolution.','draft'),
('upsc','Geography','Geomorphology & Earth''s Interior','statement_based','hard','Consider the following statements about continental drift:','महाद्वीपीय विस्थापन के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Alfred Wegener put forward the idea of a single supercontinent, Pangaea, in 1912.", "Fossils of Glossopteris and Mesosaurus found on continents now far apart were used as evidence for the theory.", "Wegener correctly identified convection currents in the mantle as the force that moves the continents."], "statements_hi": ["अल्फ़्रेड वेगनर ने 1912 में एक ही महाद्वीप, पैंजिया, का विचार रखा।", "अब बहुत दूर-दूर स्थित महाद्वीपों पर मिले ग्लॉसॉप्टेरिस और मीसोसॉरस के जीवाश्मों को इस सिद्धांत के प्रमाण के रूप में प्रस्तुत किया गया।", "वेगनर ने सही पहचाना कि प्रावार में संवहन धाराएँ महाद्वीपों को खिसकाने वाला बल हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct: the jigsaw fit of coastlines, matching rocks and glacial deposits (tillite), and shared fossils all pointed to a former union of the continents. Statement 3 is wrong: Wegener suggested ''pole-fleeing'' force and tidal force, which were too weak -- the main reason his theory was rejected. The idea of mantle convection was put forward by Arthur Holmes around 1930 and later became part of plate tectonics.','कथन 1 और 2 सही हैं: तटरेखाओं का जिगसॉ जैसा मेल, मेल खाती चट्टानें और हिमनदी निक्षेप (टिलाइट), और साझा जीवाश्म, सभी महाद्वीपों के पूर्व में जुड़े होने की ओर संकेत करते थे। कथन 3 गलत है: वेगनर ने ''ध्रुव-पलायन'' बल और ज्वारीय बल सुझाए, जो बहुत कमज़ोर थे; यही उनके सिद्धांत के अस्वीकार होने का मुख्य कारण था। प्रावार संवहन का विचार आर्थर होम्स ने लगभग 1930 में रखा, जो बाद में प्लेट विवर्तनिकी का भाग बना।','geo-continental-drift-wegener','original_pattern_matched','NCERT Class XI, Fundamentals of Physical Geography -- Distribution of Oceans and Continents.','draft'),
('upsc','Geography','Geomorphology & Earth''s Interior','statement_based','hard','Consider the following statements about earthquakes:','भूकंपों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The Richter scale is logarithmic, and an increase of one unit in magnitude corresponds to roughly 32 times more energy released.", "The Mercalli scale is a logarithmic measure of the energy released by an earthquake.", "The focus of an earthquake is the point on the surface directly above the epicentre."], "statements_hi": ["रिक्टर पैमाना लघुगणकीय है, और परिमाण में एक इकाई की वृद्धि लगभग 32 गुना अधिक ऊर्जा निकलने के बराबर है।", "मरकैली पैमाना भूकंप से निकली ऊर्जा का लघुगणकीय माप है।", "भूकंप का उद्गम केंद्र (focus) अधिकेंद्र (epicentre) के ठीक ऊपर सतह पर स्थित बिंदु है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct: each whole-number step is a tenfold increase in wave amplitude and about 32 times more energy. Statement 2 is wrong: the Mercalli scale measures intensity -- the observed effects and damage at a place, graded from I to XII -- which varies with distance and ground conditions. Statement 3 reverses the terms: the focus (hypocentre) is the point inside the Earth where the rupture begins, and the epicentre is the point on the surface directly above it.','केवल कथन 1 सही है: हर पूर्णांक चरण तरंग आयाम में दस गुना वृद्धि और लगभग 32 गुना अधिक ऊर्जा है। कथन 2 गलत है: मरकैली पैमाना तीव्रता मापता है, यानी किसी स्थान पर देखे गए प्रभाव और क्षति, जो I से XII तक श्रेणीबद्ध है, और दूरी तथा भूमि की दशाओं के साथ बदलती है। कथन 3 शब्दों को उलट देता है: उद्गम केंद्र (हाइपोसेंटर) पृथ्वी के भीतर वह बिंदु है जहाँ भ्रंशन शुरू होता है, और अधिकेंद्र उसके ठीक ऊपर सतह पर स्थित बिंदु है।','geo-earthquake-scales-focus','original_pattern_matched','NCERT Class XI, Fundamentals of Physical Geography -- Interior of the Earth.','draft'),
('upsc','Geography','Geomorphology & Earth''s Interior','statement_based','easy','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The crust is the outermost layer of the Earth.", "The Earth''s core is made up mainly of silicon and aluminium."], "statements_hi": ["भूपर्पटी पृथ्वी की सबसे बाहरी परत है।", "पृथ्वी का क्रोड मुख्य रूप से सिलिकॉन और ऐलुमिनियम से बना है।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": true}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct. Statement 2 is wrong: silicon and aluminium dominate the continental crust, which is why it is called ''sial''; the core is made mainly of nickel and iron (''nife''), which is why it is so dense.','केवल कथन 1 सही है। कथन 2 गलत है: सिलिकॉन और ऐलुमिनियम महाद्वीपीय भूपर्पटी में प्रमुख हैं, इसीलिए उसे ''सियाल'' (sial) कहते हैं; क्रोड मुख्य रूप से निकल और लोहे (''निफ़े'', nife) से बना है, इसीलिए वह इतना घना है।','geo-crust-core-composition-easy','original_pattern_matched','NCERT Class XI, Fundamentals of Physical Geography -- Interior of the Earth.','draft'),
('upsc','Geography','Geomorphology & Earth''s Interior','statement_based','easy','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Igneous rocks are formed by the cooling and solidification of magma or lava.", "Fossils are most commonly found in sedimentary rocks."], "statements_hi": ["आग्नेय चट्टानें मैग्मा या लावा के ठंडा होकर ठोस होने से बनती हैं।", "जीवाश्म सबसे अधिक अवसादी चट्टानों में मिलते हैं।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": true}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2,0.66,'Both statements are correct. Granite and basalt are igneous; sedimentary rocks such as sandstone, shale and limestone form in layers from deposited material, which preserves the remains of plants and animals -- the heat and pressure of metamorphism, or the molten origin of igneous rock, usually destroy them.','दोनों कथन सही हैं। ग्रेनाइट और बेसाल्ट आग्नेय हैं; बलुआ पत्थर, शेल और चूना पत्थर जैसी अवसादी चट्टानें जमा पदार्थों से परतों में बनती हैं, जो पौधों और जंतुओं के अवशेषों को सुरक्षित रखती हैं; कायांतरण की गर्मी और दबाव, या आग्नेय चट्टानों का पिघला हुआ मूल, प्रायः उन्हें नष्ट कर देता है।','geo-igneous-fossils-easy','original_pattern_matched','NCERT Class VII, Our Environment -- Inside Our Earth; NCERT Class XI, Fundamentals of Physical Geography -- Minerals and Rocks.','draft'),
('upsc','Geography','Geomorphology & Earth''s Interior','mcq','medium','The Mariana Trench has been formed at:','मारियाना गर्त (Mariana Trench) कहाँ बना है?','{}'::jsonb,'[{"id": "a", "body": "a continent-continent convergent boundary", "body_hi": "महाद्वीप-महाद्वीप अभिसारी सीमा पर", "isCorrect": false}, {"id": "b", "body": "a divergent boundary", "body_hi": "अपसारी सीमा पर", "isCorrect": false}, {"id": "c", "body": "an ocean-ocean convergent boundary", "body_hi": "महासागर-महासागर अभिसारी सीमा पर", "isCorrect": true}, {"id": "d", "body": "a transform boundary", "body_hi": "रूपांतर (transform) सीमा पर", "isCorrect": false}]'::jsonb,2,0.66,'The trench, containing the deepest known point in the oceans (the Challenger Deep, nearly 11 km), marks where the old, dense Pacific plate is subducting beneath the Mariana (Philippine Sea) plate; the Mariana Islands are the volcanic island arc that forms behind it. Continent-continent collision builds mountains like the Himalayas rather than deep trenches.','यह गर्त, जिसमें महासागरों का सबसे गहरा ज्ञात बिंदु (चैलेंजर डीप, लगभग 11 किमी) है, वहाँ है जहाँ पुरानी, घनी प्रशांत प्लेट मारियाना (फ़िलीपीन सागर) प्लेट के नीचे क्षेपित हो रही है; मारियाना द्वीप उसके पीछे बनने वाला ज्वालामुखी द्वीप-चाप है। महाद्वीप-महाद्वीप टक्कर गहरे गर्त नहीं, बल्कि हिमालय जैसे पर्वत बनाती है।','geo-mariana-trench-boundary','original_pattern_matched','NCERT Class XI, Fundamentals of Physical Geography -- Distribution of Oceans and Continents.','draft'),
('upsc','Geography','Geomorphology & Earth''s Interior','mcq','medium','Which one of the following layers makes up the largest part of the Earth''s volume?','निम्नलिखित में से कौन-सी परत पृथ्वी के आयतन का सबसे बड़ा भाग बनाती है?','{}'::jsonb,'[{"id": "a", "body": "The mantle", "body_hi": "प्रावार (mantle)", "isCorrect": true}, {"id": "b", "body": "The crust", "body_hi": "भूपर्पटी (crust)", "isCorrect": false}, {"id": "c", "body": "The outer core", "body_hi": "बाहरी क्रोड", "isCorrect": false}, {"id": "d", "body": "The inner core", "body_hi": "आंतरिक क्रोड", "isCorrect": false}]'::jsonb,2,0.66,'The mantle, extending from the Moho to about 2,900 km, makes up roughly 84 per cent of the Earth''s volume; the core accounts for about 15 per cent and the crust for less than 1 per cent. The core, however, holds about a third of the Earth''s mass because of its high density -- which is why ''core'' tempts.','मोहो से लगभग 2,900 किमी तक फैला प्रावार पृथ्वी के आयतन का लगभग 84 प्रतिशत है; क्रोड लगभग 15 प्रतिशत और भूपर्पटी 1 प्रतिशत से कम है। पर उच्च घनत्व के कारण क्रोड में पृथ्वी के द्रव्यमान का लगभग एक-तिहाई है; इसीलिए ''क्रोड'' आकर्षक लगता है।','geo-mantle-volume','original_pattern_matched','NCERT Class XI, Fundamentals of Physical Geography -- Interior of the Earth.','draft'),
('upsc','Geography','Geomorphology & Earth''s Interior','mcq','medium','Which one of the following landforms is produced by glacial erosion?','निम्नलिखित में से कौन-सा स्थलरूप हिमनदी अपरदन से बनता है?','{}'::jsonb,'[{"id": "a", "body": "Esker", "body_hi": "एस्कर (Esker)", "isCorrect": false}, {"id": "b", "body": "Drumlin", "body_hi": "ड्रमलिन (Drumlin)", "isCorrect": false}, {"id": "c", "body": "Moraine", "body_hi": "हिमोढ़ (Moraine)", "isCorrect": false}, {"id": "d", "body": "Cirque", "body_hi": "सर्क (Cirque)", "isCorrect": true}]'::jsonb,2,0.66,'A cirque is an armchair-shaped hollow carved at the head of a glacier; where two cirques cut back into a ridge, sharp arêtes and horns form. Eskers (winding ridges of sand and gravel laid by meltwater streams), drumlins (egg-shaped hills of till) and moraines are all deposits left by glaciers, which is what makes them tempting.','सर्क हिमनद के शीर्ष पर कटा आरामकुर्सी जैसा गर्त है; जहाँ दो सर्क किसी कटक को पीछे से काटते हैं, वहाँ तीखे अरेत और हॉर्न बनते हैं। एस्कर (पिघले जल की धाराओं से जमी रेत और बजरी की घुमावदार कटकें), ड्रमलिन (हिमोढ़ के अंडाकार टीले) और हिमोढ़, सभी हिमनदों द्वारा छोड़े गए निक्षेप हैं; यही उन्हें आकर्षक बनाता है।','geo-cirque-glacial-erosion','original_pattern_matched','NCERT Class XI, Fundamentals of Physical Geography -- Landforms and their Evolution.','draft'),
('upsc','Geography','Geomorphology & Earth''s Interior','mcq','easy','Which one of the following is the thinnest layer of the Earth?','निम्नलिखित में से कौन-सी पृथ्वी की सबसे पतली परत है?','{}'::jsonb,'[{"id": "a", "body": "The mantle", "body_hi": "प्रावार", "isCorrect": false}, {"id": "b", "body": "The crust", "body_hi": "भूपर्पटी", "isCorrect": true}, {"id": "c", "body": "The outer core", "body_hi": "बाहरी क्रोड", "isCorrect": false}, {"id": "d", "body": "The inner core", "body_hi": "आंतरिक क्रोड", "isCorrect": false}]'::jsonb,2,0.66,'The crust is only about 5 km thick under the oceans and about 30-70 km under the continents, compared with an Earth radius of about 6,370 km -- thinner, relative to the planet, than the skin of an apple.','भूपर्पटी महासागरों के नीचे केवल लगभग 5 किमी और महाद्वीपों के नीचे लगभग 30-70 किमी मोटी है, जबकि पृथ्वी की त्रिज्या लगभग 6,370 किमी है; ग्रह की तुलना में यह सेब के छिलके से भी पतली है।','geo-thinnest-layer-easy','original_pattern_matched','NCERT Class VII, Our Environment -- Inside Our Earth.','draft'),
('upsc','Geography','Geomorphology & Earth''s Interior','mcq','hard','Which one of the following is an example of a block mountain (horst)?','निम्नलिखित में से कौन-सा खंड पर्वत (होर्स्ट) का उदाहरण है?','{}'::jsonb,'[{"id": "a", "body": "The Alps", "body_hi": "आल्प्स", "isCorrect": false}, {"id": "b", "body": "The Rocky Mountains", "body_hi": "रॉकी पर्वत", "isCorrect": false}, {"id": "c", "body": "The Black Forest", "body_hi": "ब्लैक फ़ॉरेस्ट", "isCorrect": true}, {"id": "d", "body": "The Himalayas", "body_hi": "हिमालय", "isCorrect": false}]'::jsonb,2,0.66,'The Black Forest in Germany and the Vosges in France are horsts -- blocks uplifted between faults -- on either side of the Rhine rift valley (a graben), where the block between them sank. The Alps, the Rockies and the Himalayas are fold mountains formed by compression at convergent boundaries.','जर्मनी का ब्लैक फ़ॉरेस्ट और फ़्रांस का वोस्जेस होर्स्ट हैं, यानी भ्रंशों के बीच ऊपर उठे खंड, जो राइन भ्रंश घाटी (ग्राबेन) के दोनों ओर हैं, जहाँ उनके बीच का खंड नीचे धँस गया। आल्प्स, रॉकीज़ और हिमालय अभिसारी सीमाओं पर संपीडन से बने वलित पर्वत हैं।','geo-block-mountain-black-forest','original_pattern_matched','NCERT Class XI, Fundamentals of Physical Geography -- Landforms and their Evolution.','draft'),
('upsc','Geography','Geomorphology & Earth''s Interior','assertion_reason','medium','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"assertion": "Earthquakes are frequent around the Pacific ''Ring of Fire''.", "assertion_hi": "प्रशांत ''अग्नि वलय'' (Ring of Fire) के आसपास भूकंप बार-बार आते हैं।", "reason": "Earthquakes can also occur within plates, far from plate boundaries.", "reason_hi": "भूकंप प्लेटों के भीतर, प्लेट सीमाओं से दूर भी आ सकते हैं।", "ar_labels": "statement", "closing": "Which one of the following is correct in respect of the above statements?", "closing_hi": "उपर्युक्त कथनों के संदर्भ में, निम्नलिखित में से कौन-सा एक सही है?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Both Statement-I and Statement-II are correct and Statement-II is the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं और कथन-II, कथन-I की सही व्याख्या है", "isCorrect": false}, {"id": "b", "body": "Both Statement-I and Statement-II are correct and Statement-II is not the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं, किंतु कथन-II, कथन-I की सही व्याख्या नहीं है", "isCorrect": true}, {"id": "c", "body": "Statement-I is correct but Statement-II is incorrect", "body_hi": "कथन-I सही है, किंतु कथन-II गलत है", "isCorrect": false}, {"id": "d", "body": "Statement-I is incorrect but Statement-II is correct", "body_hi": "कथन-I गलत है, किंतु कथन-II सही है", "isCorrect": false}]'::jsonb,2,0.66,'Both statements are correct, but Statement-II does not explain Statement-I. The Ring of Fire is active because most of the Pacific is ringed by subduction zones where plates grind past and beneath each other. That some earthquakes occur inside plates -- as at Latur in 1993 -- is a separate fact about stress within plates.','दोनों कथन सही हैं, पर कथन-II कथन-I की व्याख्या नहीं करता। अग्नि वलय इसलिए सक्रिय है कि प्रशांत का अधिकांश भाग क्षेपण क्षेत्रों से घिरा है, जहाँ प्लेटें एक-दूसरे के पास और नीचे से रगड़ती हैं। कुछ भूकंप प्लेटों के भीतर आते हैं, जैसे 1993 में लातूर में, यह प्लेटों के भीतर के तनाव के बारे में एक अलग तथ्य है।','geo-ring-of-fire-intraplate','original_pattern_matched','NCERT Class XI, Fundamentals of Physical Geography -- Distribution of Oceans and Continents.','draft'),
('upsc','Geography','Geomorphology & Earth''s Interior','assertion_reason','medium','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"assertion": "S-waves travel through the Earth''s outer core.", "assertion_hi": "S-तरंगें पृथ्वी के बाहरी क्रोड से होकर गुज़रती हैं।", "reason": "The outer core of the Earth is liquid.", "reason_hi": "पृथ्वी का बाहरी क्रोड द्रव है।", "ar_labels": "statement", "closing": "Which one of the following is correct in respect of the above statements?", "closing_hi": "उपर्युक्त कथनों के संदर्भ में, निम्नलिखित में से कौन-सा एक सही है?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Both Statement-I and Statement-II are correct and Statement-II is the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं और कथन-II, कथन-I की सही व्याख्या है", "isCorrect": false}, {"id": "b", "body": "Both Statement-I and Statement-II are correct and Statement-II is not the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं, किंतु कथन-II, कथन-I की सही व्याख्या नहीं है", "isCorrect": false}, {"id": "c", "body": "Statement-I is correct but Statement-II is incorrect", "body_hi": "कथन-I सही है, किंतु कथन-II गलत है", "isCorrect": false}, {"id": "d", "body": "Statement-I is incorrect but Statement-II is correct", "body_hi": "कथन-I गलत है, किंतु कथन-II सही है", "isCorrect": true}]'::jsonb,2,0.66,'Statement-I is incorrect but Statement-II is correct. S-waves are transverse waves that cannot travel through liquids, so they stop at the outer core; this creates an S-wave shadow zone on the far side of the Earth beyond about 103 degrees from the epicentre, and it was this observation that showed the outer core is liquid.','कथन-I गलत है पर कथन-II सही है। S-तरंगें अनुप्रस्थ तरंगें हैं जो द्रवों से नहीं गुज़र सकतीं, इसलिए वे बाहरी क्रोड पर रुक जाती हैं; इससे अधिकेंद्र से लगभग 103 अंश से आगे पृथ्वी के दूसरी ओर S-तरंग छाया क्षेत्र बनता है, और इसी प्रेक्षण से पता चला कि बाहरी क्रोड द्रव है।','geo-s-waves-outer-core','original_pattern_matched','NCERT Class XI, Fundamentals of Physical Geography -- Interior of the Earth.','draft'),
('upsc','Geography','Geomorphology & Earth''s Interior','assertion_reason','easy','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"assertion": "Marble is a metamorphic rock.", "assertion_hi": "संगमरमर एक कायांतरित चट्टान है।", "reason": "Marble forms when limestone is changed by heat and pressure.", "reason_hi": "संगमरमर तब बनता है जब चूना पत्थर गर्मी और दबाव से बदल जाता है।", "ar_labels": "statement", "closing": "Which one of the following is correct in respect of the above statements?", "closing_hi": "उपर्युक्त कथनों के संदर्भ में, निम्नलिखित में से कौन-सा एक सही है?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Both Statement-I and Statement-II are correct and Statement-II is the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं और कथन-II, कथन-I की सही व्याख्या है", "isCorrect": true}, {"id": "b", "body": "Both Statement-I and Statement-II are correct and Statement-II is not the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं, किंतु कथन-II, कथन-I की सही व्याख्या नहीं है", "isCorrect": false}, {"id": "c", "body": "Statement-I is correct but Statement-II is incorrect", "body_hi": "कथन-I सही है, किंतु कथन-II गलत है", "isCorrect": false}, {"id": "d", "body": "Statement-I is incorrect but Statement-II is correct", "body_hi": "कथन-I गलत है, किंतु कथन-II सही है", "isCorrect": false}]'::jsonb,2,0.66,'Both statements are correct, and Statement-II explains Statement-I. Metamorphic rocks form when existing rocks are transformed without melting; in the same way shale becomes slate and sandstone becomes quartzite.','दोनों कथन सही हैं, और कथन-II कथन-I की व्याख्या करता है। कायांतरित चट्टानें तब बनती हैं जब मौजूदा चट्टानें बिना पिघले रूपांतरित हो जाती हैं; इसी तरह शेल स्लेट बनता है और बलुआ पत्थर क्वार्टज़ाइट।','geo-marble-metamorphic-easy','original_pattern_matched','NCERT Class VII, Our Environment -- Inside Our Earth; NCERT Class XI, Fundamentals of Physical Geography -- Minerals and Rocks.','draft'),
('upsc','Geography','Geomorphology & Earth''s Interior','assertion_reason','hard','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"assertion": "There are hardly any active volcanoes in the Himalayas.", "assertion_hi": "हिमालय में शायद ही कोई सक्रिय ज्वालामुखी है।", "reason": "The Himalayas were formed by the collision of two continental plates, which does not produce the deep subduction of oceanic lithosphere that generates magma.", "reason_hi": "हिमालय दो महाद्वीपीय प्लेटों की टक्कर से बना, जिससे महासागरीय स्थलमंडल का वह गहरा क्षेपण नहीं होता जो मैग्मा पैदा करता है।", "ar_labels": "statement", "closing": "Which one of the following is correct in respect of the above statements?", "closing_hi": "उपर्युक्त कथनों के संदर्भ में, निम्नलिखित में से कौन-सा एक सही है?", "fixed_option_order": true, "reason_2": "Continental crust is too thick and buoyant to be carried deep into the mantle.", "reason_2_hi": "महाद्वीपीय भूपर्पटी इतनी मोटी और उत्प्लावी है कि वह प्रावार में गहराई तक नहीं ले जाई जा सकती।"}'::jsonb,'[{"id": "a", "body": "Both Statement II and Statement III are correct and both of them explain Statement I", "body_hi": "कथन-II और कथन-III दोनों सही हैं और ये दोनों कथन-I की व्याख्या करते हैं", "isCorrect": true}, {"id": "b", "body": "Both Statement II and Statement III are correct but only one of them explains Statement I", "body_hi": "कथन-II और कथन-III दोनों सही हैं, किंतु इनमें से केवल एक ही कथन-I की व्याख्या करता है", "isCorrect": false}, {"id": "c", "body": "Only one of the Statements II and III is correct and that explains Statement I", "body_hi": "कथन-II और कथन-III में से केवल एक सही है और वही कथन-I की व्याख्या करता है", "isCorrect": false}, {"id": "d", "body": "Neither Statement II nor Statement III is correct", "body_hi": "न तो कथन-II सही है, न ही कथन-III", "isCorrect": false}]'::jsonb,2,0.66,'Both Statements II and III are correct, and both explain Statement I. In ocean-continent convergence, water released from the sinking ocean plate lowers the melting point of the mantle above it and feeds volcanoes, as in the Andes. When India met Asia, the oceanic plate between them had already been consumed, and the buoyant continental crusts crumpled and thickened instead of sinking.','कथन II और III दोनों सही हैं, और दोनों कथन I की व्याख्या करते हैं। महासागर-महाद्वीप अभिसरण में धँसती महासागरीय प्लेट से निकला जल ऊपर के प्रावार का गलनांक घटाता है और ज्वालामुखियों को मैग्मा देता है, जैसे एंडीज़ में। जब भारत एशिया से मिला, तब उनके बीच की महासागरीय प्लेट पहले ही खप चुकी थी, और उत्प्लावी महाद्वीपीय भूपर्पटियाँ धँसने के बजाय मुड़कर मोटी हो गईं।','geo-himalaya-no-volcanoes','original_pattern_matched','NCERT Class XI, Fundamentals of Physical Geography -- Distribution of Oceans and Continents.','draft'),
('upsc','Geography','Geomorphology & Earth''s Interior','match_the_following','medium','Consider the following pairs of landforms and the agents that mainly form them:','स्थलरूपों और उन्हें मुख्य रूप से बनाने वाले कारकों के निम्नलिखित युग्मों पर विचार कीजिए:','{"list_1": ["1. Yardang", "2. Esker", "3. Levee", "4. Hanging valley"], "list_1_hi": ["1. यारडंग", "2. एस्कर", "3. प्राकृतिक तटबंध (Levee)", "4. निलंबी घाटी"], "list_2": ["Wind", "Glacial meltwater", "River", "Glacier"], "list_2_hi": ["पवन", "हिमनदी पिघला जल", "नदी", "हिमनद"], "closing": "How many of the pairs given above are correctly matched?", "closing_hi": "उपर्युक्त में से कितने युग्म सही सुमेलित हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one pair", "body_hi": "केवल एक युग्म", "isCorrect": false}, {"id": "b", "body": "Only two pairs", "body_hi": "केवल दो युग्म", "isCorrect": false}, {"id": "c", "body": "Only three pairs", "body_hi": "केवल तीन युग्म", "isCorrect": false}, {"id": "d", "body": "All four pairs", "body_hi": "सभी चार युग्म", "isCorrect": true}]'::jsonb,2,0.66,'All four pairs are correct. Yardangs are streamlined ridges cut by wind in deserts; eskers are ridges of sand and gravel laid by streams flowing beneath glaciers; levees are raised banks built by a river''s floods; and hanging valleys are tributary valleys left high above a main valley that a glacier has deepened, often with waterfalls. A student who expects one mismatch will fall for ''Only three pairs''.','चारों युग्म सही हैं। यारडंग मरुस्थलों में पवन द्वारा काटी गई सुडौल कटकें हैं; एस्कर हिमनदों के नीचे बहने वाली धाराओं द्वारा जमाई रेत और बजरी की कटकें हैं; प्राकृतिक तटबंध नदी की बाढ़ों से बने ऊँचे किनारे हैं; और निलंबी घाटियाँ वे सहायक घाटियाँ हैं जो हिमनद द्वारा गहरी की गई मुख्य घाटी से बहुत ऊपर रह जाती हैं, प्रायः जलप्रपातों के साथ। जो विद्यार्थी एक बेमेल की अपेक्षा करता है, वह ''केवल तीन युग्म'' के जाल में फँसेगा।','geo-landforms-agents-pairs','original_pattern_matched','NCERT Class XI, Fundamentals of Physical Geography -- Landforms and their Evolution.','draft'),
('upsc','Geography','Oceanography & Hydrosphere','statement_based','medium','Consider the following statements about ocean currents:','महासागरीय धाराओं के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The Gulf Stream is a warm current.", "The Labrador Current is a cold current.", "The Humboldt (Peru) Current is a warm current."], "statements_hi": ["गल्फ़ स्ट्रीम एक गर्म धारा है।", "लैब्राडोर धारा एक ठंडी धारा है।", "हम्बोल्ट (पेरू) धारा एक गर्म धारा है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct: where the warm Gulf Stream meets the cold Labrador Current off Newfoundland, fog forms and plankton thrives, making the Grand Banks a famous fishing ground. Statement 3 is wrong: the Humboldt Current is cold, flowing north along the coasts of Chile and Peru; with upwelling, it supports one of the world''s richest fisheries and helps keep the Atacama dry.','कथन 1 और 2 सही हैं: जहाँ न्यूफ़ाउंडलैंड के पास गर्म गल्फ़ स्ट्रीम ठंडी लैब्राडोर धारा से मिलती है, वहाँ कोहरा बनता है और प्लवक पनपते हैं, जिससे ग्रैंड बैंक्स प्रसिद्ध मत्स्य क्षेत्र बना। कथन 3 गलत है: हम्बोल्ट धारा ठंडी है, जो चिली और पेरू के तटों के साथ उत्तर की ओर बहती है; उत्प्रवाह (upwelling) के साथ यह विश्व के सबसे समृद्ध मत्स्य क्षेत्रों में से एक को पोषित करती है और अटाकामा को शुष्क रखने में मदद करती है।','geo-ocean-currents-warm-cold','original_pattern_matched','NCERT Class XI, Fundamentals of Physical Geography -- Movements of Ocean Water.','draft'),
('upsc','Geography','Oceanography & Hydrosphere','statement_based','medium','Consider the following statements about the salinity of sea water:','समुद्री जल की लवणता के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The average salinity of the oceans is about 35 parts per thousand.", "Surface salinity is highest in the equatorial seas.", "Salinity increases where large rivers enter the sea."], "statements_hi": ["महासागरों की औसत लवणता लगभग 35 भाग प्रति हज़ार है।", "सतही लवणता विषुवतीय समुद्रों में सबसे अधिक होती है।", "जहाँ बड़ी नदियाँ समुद्र में मिलती हैं, वहाँ लवणता बढ़ जाती है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct. Statement 2 is wrong: surface salinity peaks in the subtropics, roughly between 20 and 30 degrees, where clear skies and dry sinking air drive strong evaporation; heavy daily rainfall keeps equatorial waters somewhat less salty. Statement 3 is wrong: river inflow dilutes sea water, which is why the Bay of Bengal is less saline than the Arabian Sea.','केवल कथन 1 सही है। कथन 2 गलत है: सतही लवणता उपोष्ण क्षेत्रों में, लगभग 20 से 30 अंश के बीच, सबसे अधिक होती है, जहाँ साफ़ आकाश और नीचे उतरती शुष्क वायु तेज़ वाष्पीकरण कराते हैं; रोज़ की भारी वर्षा विषुवतीय जल को कुछ कम लवणीय रखती है। कथन 3 गलत है: नदियों का जल समुद्री जल को तनु करता है, इसीलिए बंगाल की खाड़ी अरब सागर से कम लवणीय है।','geo-ocean-salinity-distribution','original_pattern_matched','NCERT Class XI, Fundamentals of Physical Geography -- Water (Oceans).','draft'),
('upsc','Geography','Oceanography & Hydrosphere','statement_based','easy','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Tides are caused mainly by the gravitational pull of the Moon.", "Spring tides occur when the Sun and the Moon are at right angles to each other with respect to the Earth."], "statements_hi": ["ज्वार-भाटा मुख्य रूप से चंद्रमा के गुरुत्वाकर्षण खिंचाव से होते हैं।", "दीर्घ ज्वार (spring tides) तब आते हैं जब पृथ्वी के सापेक्ष सूर्य और चंद्रमा एक-दूसरे से समकोण पर होते हैं।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": true}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct: the Moon''s pull, being much closer, has about twice the tide-raising effect of the Sun''s. Statement 2 describes neap tides, which are the weakest; spring tides, the highest, occur at new moon and full moon, when the Sun, the Earth and the Moon are in a straight line.','केवल कथन 1 सही है: चंद्रमा बहुत निकट होने के कारण उसके खिंचाव का ज्वार उठाने वाला प्रभाव सूर्य से लगभग दोगुना है। कथन 2 लघु ज्वार (neap tides) का वर्णन है, जो सबसे कमज़ोर होते हैं; दीर्घ ज्वार, जो सबसे ऊँचे होते हैं, अमावस्या और पूर्णिमा पर आते हैं, जब सूर्य, पृथ्वी और चंद्रमा एक सीधी रेखा में होते हैं।','geo-tides-spring-neap-easy','original_pattern_matched','NCERT Class XI, Fundamentals of Physical Geography -- Movements of Ocean Water.','draft'),
('upsc','Geography','Oceanography & Hydrosphere','statement_based','hard','Consider the following statements about El Niño and La Niña:','एल नीनो और ला नीना के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["El Niño is an unusual warming of the surface waters of the central and eastern equatorial Pacific.", "During El Niño, the upwelling of cold, nutrient-rich water off Peru weakens, hurting its fisheries.", "La Niña is associated with weaker than normal trade winds across the Pacific."], "statements_hi": ["एल नीनो मध्य और पूर्वी विषुवतीय प्रशांत के सतही जल का असामान्य रूप से गर्म होना है।", "एल नीनो के दौरान पेरू के पास ठंडे, पोषक-समृद्ध जल का उत्प्रवाह कमज़ोर पड़ जाता है, जिससे वहाँ की मत्स्य-पालन को हानि होती है।", "ला नीना प्रशांत पर सामान्य से कमज़ोर व्यापारिक पवनों से जुड़ा है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct: the name, ''the Child'', comes from Peruvian fishermen who noticed warm water arriving around Christmas, when fish catches fell. Statement 3 is wrong: La Niña is the opposite phase -- stronger trade winds pile warm water in the western Pacific and intensify upwelling off South America, cooling the eastern Pacific; El Niño is the phase in which the trades weaken.','कथन 1 और 2 सही हैं: यह नाम, ''बालक'', पेरू के मछुआरों से आया, जिन्होंने क्रिसमस के आसपास गर्म जल आते देखा, जब मछली पकड़ कम हो जाती थी। कथन 3 गलत है: ला नीना विपरीत चरण है; अधिक तेज़ व्यापारिक पवनें गर्म जल को पश्चिमी प्रशांत में जमा करती हैं और दक्षिण अमेरिका के पास उत्प्रवाह तेज़ करती हैं, जिससे पूर्वी प्रशांत ठंडा होता है; एल नीनो वह चरण है जिसमें व्यापारिक पवनें कमज़ोर पड़ती हैं।','geo-el-nino-la-nina','original_pattern_matched','NCERT Class XI, Fundamentals of Physical Geography -- Atmospheric Circulation and Weather Systems; India Meteorological Department -- ENSO.','draft'),
('upsc','Geography','Oceanography & Hydrosphere','mcq','medium','The Gulf Stream originates in the:','गल्फ़ स्ट्रीम का उद्गम कहाँ होता है?','{}'::jsonb,'[{"id": "a", "body": "Gulf of Mexico", "body_hi": "मेक्सिको की खाड़ी", "isCorrect": true}, {"id": "b", "body": "Labrador Sea", "body_hi": "लैब्राडोर सागर", "isCorrect": false}, {"id": "c", "body": "Bay of Biscay", "body_hi": "बिस्के की खाड़ी", "isCorrect": false}, {"id": "d", "body": "Gulf of Guinea", "body_hi": "गिनी की खाड़ी", "isCorrect": false}]'::jsonb,2,0.66,'The current flows out of the Gulf of Mexico through the Strait of Florida, runs along the east coast of the United States and, as the North Atlantic Drift, carries warmth to north-western Europe -- which is why ports in Norway stay ice-free in winter while those at similar latitudes in Canada freeze.','यह धारा मेक्सिको की खाड़ी से फ़्लोरिडा जलडमरूमध्य होकर निकलती है, अमेरिका के पूर्वी तट के साथ बहती है और उत्तरी अटलांटिक प्रवाह के रूप में उत्तर-पश्चिमी यूरोप तक गर्मी ले जाती है; इसीलिए नॉर्वे के बंदरगाह सर्दियों में हिम-मुक्त रहते हैं जबकि कनाडा में समान अक्षांशों वाले बंदरगाह जम जाते हैं।','geo-gulf-stream-origin','original_pattern_matched','NCERT Class XI, Fundamentals of Physical Geography -- Movements of Ocean Water.','draft'),
('upsc','Geography','Oceanography & Hydrosphere','assertion_reason','medium','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"assertion": "Tsunamis are most often generated by undersea earthquakes.", "assertion_hi": "सुनामी प्रायः समुद्र के नीचे आने वाले भूकंपों से उत्पन्न होती हैं।", "reason": "Tsunamis are caused mainly by strong winds blowing over the open ocean.", "reason_hi": "सुनामी मुख्य रूप से खुले महासागर पर चलने वाली तेज़ हवाओं से होती हैं।", "ar_labels": "statement", "closing": "Which one of the following is correct in respect of the above statements?", "closing_hi": "उपर्युक्त कथनों के संदर्भ में, निम्नलिखित में से कौन-सा एक सही है?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Both Statement-I and Statement-II are correct and Statement-II is the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं और कथन-II, कथन-I की सही व्याख्या है", "isCorrect": false}, {"id": "b", "body": "Both Statement-I and Statement-II are correct and Statement-II is not the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं, किंतु कथन-II, कथन-I की सही व्याख्या नहीं है", "isCorrect": false}, {"id": "c", "body": "Statement-I is correct but Statement-II is incorrect", "body_hi": "कथन-I सही है, किंतु कथन-II गलत है", "isCorrect": true}, {"id": "d", "body": "Statement-I is incorrect but Statement-II is correct", "body_hi": "कथन-I गलत है, किंतु कथन-II सही है", "isCorrect": false}]'::jsonb,2,0.66,'Statement-I is correct but Statement-II is incorrect. A tsunami forms when a sudden vertical movement of the sea floor -- usually at a subduction zone, sometimes from a landslide or volcanic eruption -- displaces a huge column of water. Wind produces ordinary waves and storm surges, which affect only the upper layer of the sea, whereas a tsunami moves the whole water column and can cross oceans at jet-aircraft speed.','कथन-I सही है पर कथन-II गलत है। सुनामी तब बनती है जब समुद्र तल की अचानक ऊर्ध्वाधर हलचल, प्रायः किसी क्षेपण क्षेत्र में, कभी भूस्खलन या ज्वालामुखी उद्गार से, जल के एक विशाल स्तंभ को विस्थापित कर देती है। हवा सामान्य लहरें और तूफ़ानी महोर्मि (storm surge) पैदा करती है, जो समुद्र की केवल ऊपरी परत को प्रभावित करती हैं, जबकि सुनामी पूरे जल-स्तंभ को हिलाती है और जेट विमान की गति से महासागर पार कर सकती है।','geo-tsunami-cause','original_pattern_matched','NCERT Class XI, Fundamentals of Physical Geography -- Movements of Ocean Water; Indian National Centre for Ocean Information Services -- Tsunami Early Warning.','draft'),
('upsc','Geography','Oceanography & Hydrosphere','assertion_reason','hard','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"assertion": "The western coasts of continents in the tropics and subtropics often have deserts.", "assertion_hi": "उष्णकटिबंध और उपोष्ण कटिबंध में महाद्वीपों के पश्चिमी तटों पर प्रायः मरुस्थल होते हैं।", "reason": "Cold ocean currents flowing along these coasts cool the air above them and reduce its capacity to hold moisture.", "reason_hi": "इन तटों के साथ बहने वाली ठंडी महासागरीय धाराएँ ऊपर की वायु को ठंडा करती हैं और उसकी नमी धारण करने की क्षमता घटाती हैं।", "ar_labels": "statement", "closing": "Which one of the following is correct in respect of the above statements?", "closing_hi": "उपर्युक्त कथनों के संदर्भ में, निम्नलिखित में से कौन-सा एक सही है?", "fixed_option_order": true, "reason_2": "Coastal fog on several of these deserts supports specialised plants and animals.", "reason_2_hi": "इनमें से कई मरुस्थलों पर तटीय कोहरा विशिष्ट पौधों और जंतुओं को सहारा देता है।"}'::jsonb,'[{"id": "a", "body": "Both Statement II and Statement III are correct and both of them explain Statement I", "body_hi": "कथन-II और कथन-III दोनों सही हैं और ये दोनों कथन-I की व्याख्या करते हैं", "isCorrect": false}, {"id": "b", "body": "Both Statement II and Statement III are correct but only one of them explains Statement I", "body_hi": "कथन-II और कथन-III दोनों सही हैं, किंतु इनमें से केवल एक ही कथन-I की व्याख्या करता है", "isCorrect": true}, {"id": "c", "body": "Only one of the Statements II and III is correct and that explains Statement I", "body_hi": "कथन-II और कथन-III में से केवल एक सही है और वही कथन-I की व्याख्या करता है", "isCorrect": false}, {"id": "d", "body": "Neither Statement II nor Statement III is correct", "body_hi": "न तो कथन-II सही है, न ही कथन-III", "isCorrect": false}]'::jsonb,2,0.66,'Both Statements II and III are correct, but only Statement II explains Statement I. Air cooled from below by currents such as the Benguela, Canary, California and Humboldt becomes stable, so it does not rise to form rain clouds -- producing the Namib, the western Sahara, and the Atacama, the driest of all. Statement III is true -- coastal fog is the main source of water for many organisms there -- but it is a consequence of the cold currents, not a reason for the dryness.','कथन II और III दोनों सही हैं, पर केवल कथन II कथन I की व्याख्या करता है। बेंगुएला, कैनरी, कैलिफ़ोर्निया और हम्बोल्ट जैसी धाराओं से नीचे से ठंडी हुई वायु स्थिर हो जाती है, इसलिए वह वर्षा के बादल बनाने के लिए ऊपर नहीं उठती; इसी से नामिब, पश्चिमी सहारा, और सबसे शुष्क, अटाकामा बनते हैं। कथन III सही है, वहाँ के कई जीवों के लिए तटीय कोहरा जल का मुख्य स्रोत है, पर यह ठंडी धाराओं का परिणाम है, शुष्कता का कारण नहीं।','geo-west-coast-deserts-cold-currents','original_pattern_matched','NCERT Class XI, Fundamentals of Physical Geography -- Movements of Ocean Water; World Climate and Climate Change.','draft')
